#include "Driver_WINGCTRL.h"

/**
 * @brief  Get magic from Wing Control Register.
 *
 * @return Magic number.
 *
 */
wm_base_t wingctrl_MagicGet(void)
{
    return WING_CRTL->MAGIC;
}

/**
 * @brief  Set soft reset PC address.
 *
 * @param[in]  addr   Soft reset PC address.
 *
 */
void wingctrl_SoftResetPCSet(wm_base_t addr)
{
    WM_ASSERT(0 == (addr & 0x01));

    WING_CRTL->SOFT_RESET_ADDR = addr;
}

/**
 * @brief  Set hard reset PC address.
 *
 * @param[in]  addr   Hard reset PC address.
 *
 */
void wingctrl_HardResetPCSet(wm_base_t addr)
{
    WM_ASSERT(0 == (addr & 0x01));

    WING_CRTL->HARD_RESET_ADDR = addr;
}

/**
 * @brief  Set NMI handler address.
 *
 * @param[in]  addr   NMI handler address.
 *
 */
void wingctrl_NMIHandlerAddrSet(wm_base_t addr)
{
    WM_ASSERT(0 == (addr & 0x3));

    WING_CRTL->MNVEC = addr;
}

/**
 * @brief  Set NMI trigger.
 *
 * @param[in]  trigger   NMI trigger.
 *
 */
void wingctrl_NMITriggerSet(bool trigger)
{
    WING_CRTL->NMI_TRIGGER = trigger;
}

/**
 * @brief  Set external interrupt trigger.
 *
 * @param[in]  irq      Number of interrupt input.
 * @param[in]  trigger  External interrupt trigger.
 *
 */
void wingctrl_ExtIntTrigger(INT_TYPE irq, bool trigger)
{
    WM_ASSERT((64 == irq) || (65 == irq));

    // edge mode
#if defined(__CLIC_PRESENT) && (__CLIC_PRESENT == 1)
    if (__clic_GetIntTrig(irq) & 0x2)
#else
    if (1)
#endif
    {
        if (trigger)
        {
            WING_CRTL->EXT_INT_TRIGGER |= (2 << ((irq - 64) * 2));
        }
    }

    // level mode
    else
    {
        if (trigger)
        {
            WING_CRTL->EXT_INT_TRIGGER |= (1 << ((irq - 64) * 2));
        }

        else
        {
            WING_CRTL->EXT_INT_TRIGGER &= ~(1 << ((irq - 64) * 2));
        }
    }
}

