        case 3:
            pmacfg = __CSR_READ(CSR_PMACFG3);
            break;
        case 4:
            pmacfg = __CSR_READ(CSR_PMACFG4);
            break;
        case 5:
            pmacfg = __CSR_READ(CSR_PMACFG5);
            break;
        case 6:
            pmacfg = __CSR_READ(CSR_PMACFG6);
            break;
        case 7:
            pmacfg = __CSR_READ(CSR_PMACFG7);
            break;
        case 8:
            pmacfg = __CSR_READ(CSR_PMACFG8);
            break;
        case 9:
            pmacfg = __CSR_READ(CSR_PMACFG9);
            break;
        case 10:
            pmacfg = __CSR_READ(CSR_PMACFG10);
            break;
        case 11:
            pmacfg = __CSR_READ(CSR_PMACFG11);
            break;
        case 12:
            pmacfg = __CSR_READ(CSR_PMACFG12);
            break;
        case 13:
            pmacfg = __CSR_READ(CSR_PMACFG13);
            break;
        case 14:
            pmacfg = __CSR_READ(CSR_PMACFG14);
            break;
        case 15:
            pmacfg = __CSR_READ(CSR_PMACFG15);
            break;
        default:
            break;
    }

    return pmacfg;
}

/**
 * @brief  Set PMACFGx by csr index.
