 *
 */
__STATIC_FORCEINLINE wm_status_t __pma_SetEntryMemAttr(wm_base_t entry, PMA_MEM_ATTR_TYPE attr, PMP_MEM_OUTER_ALLOCATE_TYPE outer_al, PMP_MEM_INNER_ALLOCATE_TYPE inner_al, PMP_SHAREABLE_ATTR_TYPE sh)
{
    wm_status_t ret = RET_OK;
    uint8_t  cfg;
    wm_csr_t reg;

    WM_ASSERT_RET(entry < __PMP_ENTRY_NUM, RET_ERR_PMP_ENTRY_NUM_UNVALID);
    WM_ASSERT_RET((attr >= DEFAULT_PMA) && (attr <= MEM_OUTER_C_INNER_C), RET_ERR_PMA_ATTR_UNVALID);

    reg = __pmp_GetAddr(entry);
    reg &= (~(0x03 << 30));
    reg |= (sh << 30);
    ret = __pmp_SetAddr(entry, reg);
    WM_CHECK_RET(ret);

    cfg = __pma_GetXCfg(entry);

    /* clear PMA Attribute fields */
    cfg &= 0x33;

    switch (attr)
    {
        case DEFAULT_PMA:
            /* Default PMA, no special configuration */
            cfg = 0x00;
            break;

        case DEV_NGNRNE:
            /* Device-nGnRnE, no allocate configuration */
            cfg |= 0x0c;
            break;

        case MEM_OUTER_NC_INNER_NC:
            /* Memory,Outer non-cacheable,Inner non-cacheable */
            cfg |= 0x44;
            break;

        case MEM_OUTER_NC_INNER_C:
            /* Memory,Outer non-cacheable,Inner cacheable */
            cfg |= 0x48;
            break;

        case MEM_OUTER_C_INNER_NC:
            /* Memory,Outer cacheable,Inner non-cacheable */
            cfg |= 0x84;
            break;

        case MEM_OUTER_C_INNER_C:
            /* Memory,Outer cacheable,Inner cacheable */
            cfg |= 0x88;
            break;

        default:
            break;
    }

    if (attr >= MEM_OUTER_NC_INNER_NC)
    {
        /* clear Allocate fields */
        cfg &= 0xcc;

        /* Set allocate configuration */
        cfg |= (outer_al | inner_al);
    }

    ret = __pma_SetXCfg(entry, cfg);

    return ret;
}

/** @}  End of Group WMSIS_PMA_Funtions */
