/**
 * @brief  Tools function for caculating one number of given NAPOT address low part. 
 * 
 * @param[in]  data   Number of one. 
 */
__STATIC_FORCEINLINE uint8_t count_trailing_ones(wm_csr_t data)
{
    uint8_t num = 0;

#ifdef __riscv_isa_zbb
    num = __riscv_ctz_32(~data);
#else
    while (data & 0x01)
    {
        num++;
        data = data >> 1;
    }
#endif
    return num;
}

/**
 * @brief  Get pmp configuration of given entry.
 * @details This function is only use for NAPOT region, other address
 * matching mode should use __pmp_GetAddr and __pmp_GetXCfg.
 * 
 * @param[in]   entry   PMP entry index to get.
 * @param[out]  cfg     Configuration of given entry.
 * 
 * @retval RET_OK   If the procedure was successful. 
 * @retval RET_ERR_PMP_ENTRY_NUM_UNVALID   Given entry is unvalid. 
 */
__STATIC_FORCEINLINE wm_status_t __pmp_GetEntry(wm_base_t entry, PMP_CFG *cfg)
{
    wm_status_t ret = RET_OK;
    wm_csr_t    cur_addr;
    uint8_t     num;

    WM_ASSERT_RET(entry < __PMP_MIN_REGION_SIZE, RET_ERR_PMP_ENTRY_NUM_UNVALID);

    cfg->xcfg = __pmp_GetXCfg(entry);
    cur_addr  = __pmp_GetAddr(entry);

    if ((cfg->xcfg & PMP_MATCH_MODE_MSK) == PMP_TOR)
    {
        cfg->base_addr = cur_addr << 2;
        cfg->order     = 2;
    }
    else
    {
        num = count_trailing_ones(cur_addr);
        cur_addr &= ~((1 << num) - 1) ;

        cfg->base_addr = cur_addr << 2;
        cfg->order     = num + 2;
    }

    return ret;
}

/**
 * @brief  Set pmp configuration of given entry.
 * @details This function is only use for NAPOT region, other address
 * matching mode should use __pmp_SetAddr and __pmp_SetXCfg.
 * 
 * @param[in]   entry   PMP entry index to set.
 * @param[out]  cfg   Configuration to set for given entry.
 * 
 * @retval RET_OK   If the procedure was successful. 
 * @retval RET_ERR_PMP_ENTRY_NUM_UNVALID   Given entry is unvalid. 
 * @retval RET_ERR_PMP_ADDR_NOT_ALIGNED   Given addr is not aligned. 
 * @retval RET_ERR_PMP_PERMISSION_RSVD   Given permission is reserved. 
 * @retval RET_ERR_PMP_CUR_API_UNVALID   Given address matching mode is not support by this function. 
 * @retval RET_ERR_PMP_ENRTY_LOCKED   PMP entry is locked, changing configuration is not allowed. 
 * @retval RET_ERR_PMP_ENTRY_SIZE_UNVALID   Given size is unvalid. 
 */
__STATIC_FORCEINLINE wm_status_t __pmp_SetEntry(wm_base_t entry, PMP_CFG *cfg)
{
    wm_status_t ret = RET_OK;
    uint8_t  csr_cfg;
    uint32_t size, addr;

    WM_ASSERT_RET(entry < __PMP_ENTRY_NUM, RET_ERR_PMP_ENTRY_NUM_UNVALID);

    WM_ASSERT_RET(0 == (cfg->base_addr % __PMP_MIN_REGION_SIZE), RET_ERR_PMP_ADDR_NOT_ALIGNED);

#if !defined(__SMEPMP_PRESENT) || (__SMEPMP_PRESENT == 0)
    WM_ASSERT_RET((0 != (cfg->xcfg & PMP_R) || (0 == (cfg->xcfg & PMP_W))), RET_ERR_PMP_PERMISSION_RSVD);
#endif

    WM_ASSERT_RET(PMP_TOR != ((cfg->xcfg) & PMP_MATCH_MODE_MSK), RET_ERR_PMP_CUR_API_UNVALID);

    csr_cfg = __pmp_GetXCfg(entry);

    /* PMP lock bit can not be cleared once set,when SMEPMP not supported */
#if !defined(__SMEPMP_PRESENT) || (__SMEPMP_PRESENT == 0)    
    WM_ASSERT_RET(0 == (csr_cfg & PMP_L), RET_ERR_PMP_ENRTY_LOCKED);
#endif

    ret = __pmp_SetXCfg(entry, cfg->xcfg);
    WM_CHECK_RET(ret);

    addr = (cfg->base_addr) >> 2;
    size = (1 << (cfg->order));
    WM_ASSERT_RET(size >= __PMP_MIN_REGION_SIZE, RET_ERR_PMP_ENTRY_SIZE_UNVALID);
    addr += (size - 1) >> 2;

    ret = __pmp_SetAddr(entry, addr);

    return ret;
}

