#if defined(__PMU_PRESENT) && (__PMU_PRESENT == 1)
/**
 * @brief  Get the count value from the Performance Monitoring Unit (PMU). 
 * @details The function reads from the appropriate control and status registers (CSRs)  
 * based on the RISC-V XLEN and PMU width to obtain the PMU count value. 
 * @param[in]  pmu    The base CSR for the performance monitoring unit. 
 * @param[in]  pmu_h  The high CSR register (used when PMU width is 64 bits).  
 * @return  Returns the 64-bit PMU count value. 
 */  
__STATIC_FORCEINLINE uint64_t __get_pmuCount(wm_csr_t pmu, wm_csr_t pmu_h)
{
#if __riscv_xlen == 64
    return (uint64_t)__CSR_READ(pmu);
#elif (__riscv_xlen == 32) && (__PMU_WIDTH == 32)
    return (uint64_t)__CSR_READ(pmu);
#elif (__riscv_xlen == 32) && (__PMU_WIDTH == 64)
    volatile uint32_t low;
    volatile uint32_t high0;
    volatile uint32_t high1;
    uint64_t          full;

    high0 = __CSR_READ(pmu_h);
    low   = __CSR_READ(pmu);
    high1 = __CSR_READ(pmu_h);
    if (high0 != high1) {
        low = __CSR_READ(pmu);
    }
    full = (((uint64_t)high1) << 32) | low;
    return full;
#else
    #error "__riscv_xlen or __PMU_WIDTH invalid.\n"
#endif
}

/**
 * @brief  Get the number of cycles since the last reset.
 * @details This function calls the __get_pmuCount function to obtain the value of the   
 * machine cycle counter (MCYCLE), which counts the total number of   
 * clock cycles executed since the last reset. 
 * @return  Returns the current value of the cycle counter as a uint64_t.
 * @remarks It will work for both RV32 and RV64 to get full 64bits value of MCYCLE
 */
__STATIC_FORCEINLINE uint64_t __get_mcycle(void)
{
    return __get_pmuCount(CSR_MCYCLE, CSR_MCYCLEH);
}

/**
 * @brief  Get the number of instructions executed since the last reset. 
 * @details This function calls the __get_pmuCount function to obtain the value of the   
 * machine instructions retired counter (MINSTRET), which counts the total number of   
 * instructions that have been executed since the last reset.  
 * @return  Returns the current value of the instruction counter as a uint64_t.
 * @remarks It will work for both RV32 and RV64 to get full 64bits value of MINSTRET
 */
__STATIC_FORCEINLINE uint64_t __get_minstret(void)
{
    return __get_pmuCount(CSR_MINSTRET, CSR_MINSTRETH);
}

/**
 * @brief  Retrieves the current cycle count from the cycle counter.
 * @details This function calls the __get_pmuCount function to obtain the value of the   
 * cycle counter (CYCLE), which counts the number of clock cycles since the   
 * last reset. 
 * @return  Returns the current value of the cycle counter as a uint64_t.
 * @remarks It will work for both RV32 and RV64 to get full 64bits value of CYCLE
 */
__STATIC_FORCEINLINE uint64_t __get_cycle(void)
{
    return __get_pmuCount(CSR_CYCLE, CSR_CYCLEH);
}

/**
 * @brief  Retrieves the current instruction count from the instruction counter. 
 * @details This function calls the __get_pmuCount function to obtain the value of the   
 * instruction counter (INSTRET), which counts the total number of instructions   
 * executed since the last reset.  
 * @return  Returns the current value of the instruction counter as a uint64_t.
 * @remarks It will work for both RV32 and RV64 to get full 64bits value of INSTRET
 */
__STATIC_FORCEINLINE uint64_t __get_instret(void)
{
    return __get_pmuCount(CSR_INSTRET, CSR_INSTRETH);
}

/**
 * @brief  Retrieves the current time value from the timer counter.  
 * @details This function calls the __get_pmuCount function to obtain the value of the   
 * timer counter (TIME), which counts the number of clock cycles since the   
 * last reset or since the timer was last set.
 * @return  Returns the current value of the timer counter as a uint64_t.
 * @remarks It will work for both RV32 and RV64 to get full 64bits value of TIME
 * @attention only available when user mode available
 */
__STATIC_FORCEINLINE uint64_t __get_time(void)
{
    return __get_pmuCount(CSR_TIME, CSR_TIMEH);
}

