 /* System Timer Feature Configuration Macro:
 * 1. __SYSTIMER_PRESENT: Must, Define whether Private System Timer is present or not.
 *   * 0: Not present
 *   * 1: Present
 * 2. __TIMER_REG_BASEADDR: Must, Define the base address of the System Timer.
 * 3. __CLIC_PRESENT: Optional, Define whether CLIC is present or nor. If not present 
 */
/**
 * @defgroup WMSIS_Core_SysTimer_Registers     Register Define and Type Definitions Of System Timer
 * @ingroup WMSIS_Core_Registers
 * @brief  Type definitions and defines for system timer registers.
 *
 * @{
 */

/* SysTick Timer Control / Status Register Definitions */
#define MTIMECTL_TIMEEN_POS                             (0U)                                        /*!< SysTick Timer MTIMECTL: TIMESTOP bit Position */
#define MTIMECTL_TIMEEN_MSK                             (1UL << MTIMECTL_TIMEEN_POS)                /*!< SysTick Timer MTIMECTL: TIMESTOP Mask */
#define MTIMECTL_CMPCLREN_POS                           (1U)                                        /*!< SysTick Timer MTIMECTL: CMPCLREN bit Position */
#define MTIMECTL_CMPCLREN_MSK                           (1UL << MTIMECTL_CMPCLREN_POS)              /*!< SysTick Timer MTIMECTL: CMPCLREN Mask */

#define MSIP_MSIP_POS                                   (0U)                                        /*!< SysTick Timer MSIP: MSIP bit Position */
#define MSIP_MSIP_MSK                                   (1UL << MSIP_MSIP_POS)                      /*!< SysTick Timer MSIP: MSIP*/

#define SRCR_RREQ_POS                                   (0U)                                        /*!< SysTick Timer SRCR rreq Position*/
#define SRCR_RREQ_MSK                                   (1UL << SRCR_RREQ_POS)                      /*!< SysTick Timer SRCR RREQ*/

/**
  * @struct SysTimer_MMR
  * @brief  Structure type to access the System timer Register(SysTimer).
  * @details Structure definition to access the System timer Register(SysTimer).
  * @note If System timer is 32bit, MTIME_HI, MTIMECMP, MTIMECALIB_HI register is reserved.
  */
typedef struct {
    __IOM uint32_t MTIME_LO;                            /*!< Offset: 0x000 (R/W)  Supported Parallel Port Size Register */
    __IOM uint32_t MTIME_HI;                            /*!< Offset: 0x004 (R/W)  Supported Parallel Port Size Register */
    __IOM uint32_t MTIMECMP_LO;                         /*!< Offset: 0x008 (R/W)  Supported Parallel Port Size Register */
    __IOM uint32_t MTIMECMP_HI;                         /*!< Offset: 0x00c (R/W)  Supported Parallel Port Size Register */
    __IOM uint32_t MTIMECTL;                            /*!< Offset: 0x010 (R/W)  Supported Parallel Port Size Register */
    __IOM uint32_t RESV0[0x3];                          /*!< Offset: 0x014 - 0x01c Reserved */
    __IOM uint32_t MSIP;                                /*!< Offset: 0x020 (R/W)  Supported Parallel Port Size Register */
    __IOM uint32_t RESV1[0x1];                          /*!< Offset: 0x024 Reserved */
    __IM  uint32_t MTIMECALIB_LO;                       /*!< Offset: 0x028 (R/W)  Supported Parallel Port Size Register */
    __IM  uint32_t MTIMECALIB_HI;                       /*!< Offset: 0x02c (R/W)  Supported Parallel Port Size Register */
    __IOM uint32_t SRCR;                                /*!< Offset: 0x030 (R/W)  Supported Parallel Port Size Register */
} SysTimer_MMR;

/* System Timer Memory mapping of Device  */
#define SysTimer_BASE                    __TIMER_REG_BASEADDR                           /*!< SysTimer Base Address */
#define SysTimer                         ((SysTimer_MMR *) SysTimer_BASE)               /*!< SysTimer configuration struct */

/** @} end of group WMSIS_Core_SysTimer_Registers */

#if defined(__TIMER_PRESENT) && (__TIMER_PRESENT == 1)
/**
 * @defgroup WMSIS_SysTimer_Funtions System Timer Functions
 * @ingroup WMSIS_Core_functions
 * @brief   Functions that configure the Core System Timer.
 * @{
 */

/** 
 * @brief  Set System Timer Load value
 * @details Set the system timer load value in MTIMER register.
 * @param[in]  value  value to set system timer MTIMER register.
 * @note    Load value is 64bit wide. 
 * If Systimer is 24 bit, load the low 24 bit of load value to MTIME_LO register.
 * If Systimer is 32 bit, load the low 32 bit of load value to MTIME_LO register.
 * If Systimer is 64 bit, load the low 32 bit of load value to MTIME_LO register, load the high 32 bit of load value to MTIME_LO register.  
 * \ref SysTimer_GetLoadCnt
 */
__STATIC_FORCEINLINE void SysTimer_SetLoadCnt(uint64_t value) {
    SysTimer->MTIME_LO = (uint32_t)value;
}
/**
 * @brief  Get System Timer Load value
 * @details Read MTIMER register and return the load value in MTIMER register.
 * @note    If Systimer is 24 or 32 bit, read the low 24 bit to MTIME_LO register and return .
 * @return  current value(64bit) of system timer MTIMER register.
 */
__STATIC_FORCEINLINE uint64_t SysTimer_GetLoadCnt(void)
{
    return SysTimer->MTIME_LO;
}

/**
 * @brief  Set Systimer Timer Compare value
 * @details Set MTIMERCMP_LO register. If MTIME value >= MTIMERCMP, MIP.MTIP will set and generate timer interrupt.
 * @param[in]  value  The value load to MTIMERCMP register.
 * @note    If Systemtimer is 24 or 32 bit, load low 24 bit of value to MTIMERCMP, MTIMERCMP_HI is resvrved.
 * @return 
 */
__STATIC_FORCEINLINE void SysTimer_SetCompareCnt(uint64_t value)
{
    SysTimer->MTIMECMP_LO = (uint32_t)value;
}

/**
 * @brief  Get Systimer Timer Compare value.
 * @details Read MTIMERCMP_LO register and return.
 * @return  Systimer Timer Compare value in MTIMERCMP.
 */
__STATIC_FORCEINLINE uint32_t SysTimer_GetCompareCnt(void)
{
    return SysTimer->MTIMECMP_LO;
}

/**
 * @brief  Enable SysTimer counter countinues counting.
 * @details This function will Set MTIMECTL.en bit. The counter is enabled and countinues counting when  mtimectl.en is set. 
 * Otherwise, the counter is disabled.
 * When enabled, the counter incrementally counts until the value reaches mtimecmp. 
 * @return None
 */
__STATIC_FORCEINLINE void SysTimer_Start(void)
{
    SysTimer->MTIMECTL |= (MTIMECTL_TIMEEN_MSK);
}

/**
 * @brief  Disable SysTimer counter count.
 * @details Clear MTIMECTL.en bit. When mtimectl.en is Cleared the counter is disabled.
 * @return  None
 */
__STATIC_FORCEINLINE void SysTimer_Stop(void)
{
    SysTimer->MTIMECTL &= ~(MTIMECTL_TIMEEN_MSK);
}

/**
 * @brief  Set MTIMECTL register.
 * @details Set mctl to MTIMECTL register. 
 * @param[in]  mctl  Tne value load to MTIMECTL register.
 * @return  None
 */
__STATIC_FORCEINLINE void SysTimer_SetControlValue(uint32_t mctl)
{
    SysTimer->MTIMECTL = mctl;
}

/**
 * @brief  Get MTIMECTL register value.
 * @details Read MTIMECTL register value and return.
 * @return  MTIMECTL register value.
 */
__STATIC_FORCEINLINE uint32_t SysTimer_GetControlValue(void)
{
    return SysTimer->MTIMECTL;
}

/**
 * @brief  Read MTIMECALIB register.
 * @details Read MTIMECALIB register which provides calibration value for the timer and return.
 * @return  Calibration value for the timer
 */
__STATIC_FORCEINLINE uint32_t SysTimer_GetCalibValue(void)
{
    return SysTimer->MTIMECALIB_LO;
}

/**
 * @brief  Generate the software interrupt to the hart.
 * @details Set MSIP.msip bit presents the level-triggered software interrupt to the hart, which records into mip. msip.
 * @return  None
 */
__STATIC_FORCEINLINE void SysTimer_SetSWIRQ(void)
{
    SysTimer->MSIP |= MSIP_MSIP_MSK;
}

/**
 * @brief  Clear software interrupt pending state.
 * @details Clear MSIP.msip bit and clear the pending state of the level-triggered software interrupt.
 * @return  None
 */
__STATIC_FORCEINLINE void SysTimer_ClearSWIRQ(void)
{
    SysTimer->MSIP &= ~MSIP_MSIP_MSK;
}

/**
 * @brief  Generate the software reset request.
 * @details Set SRCR.rreq bit and request a software reset.
 * @return  None
 */
__STATIC_FORCEINLINE void SysTimer_SoftwareReset(void)
{
    SysTimer->SRCR = SRCR_RREQ_MSK;
    // wait for request
    while (1);
}
/** @} End of group WMSIS_SysTimer_Funtions  */
#if defined(__CLIC_PRESENT) && (__CLIC_PRESENT == 1)  

/**  
 * @defgroup WMSIS_SystemTick_Functions System Tick Config Functions
   @ingroup  WMSIS_SystemTick_Functions
   @details  Provide functions to config system tick used by OS.
 * @{
 */

/**
 * @brief  System Tick Configuration
 * @details Initializes the System Timer and its interrupt, and starts the System Tick Timer.
            Counter is in free running mode to generate periodic interrupts.
 * 
 * @param[in]  ticks  Number of ticks between two interrupts.
 * @return            0  Function succeeded.
             0x80070000  Function fail. ticks should not be zero.
 * @note    In our default implementation, the timer counter will be set to zero, and it will start a timer interrupt when it matchs the ticks user set, 
 *          during the timer interrupt user should reload the system tick using \ref SysTick_Reload function or similar function written by user, 
 *          so it can produce period timer interrupt. This function only available when __SYSTIMER_PRESENT == 1 and __CLIC_PRESENT == 1 
 */
__STATIC_FORCEINLINE wm_status_t SysTick_Config(uint64_t ticks)
{   
    WM_ASSERT_RET(((uint32_t)ticks), RET_ERR_MTIMER_TICKS_INVALID);
    SysTimer_SetLoadCnt(0);
    SysTimer_SetCompareCnt((uint32_t)ticks);

    /* enable machine timer interrupt */
    __clic_ClearIntPending(TIMER_INT);
    __clic_EnableInt(TIMER_INT);
    return RET_OK;
}
#else // if defined (__CLIC_PRESENT) && (__CLIC_PRESENT == 1)

/**
 * @brief  System Tick Configuration
 * @details Initializes the System Timer and its interrupt, and starts the System Tick Timer.
 * @param[in]   ticks  Number of ticks between two interrupts.
 * @return            0  Function succeeded.
             0x80070000  Function fail. ticks should not be zero.
 * @note    In our default implementation, the timer counter will be set to zero, and it will start a timer interrupt when it matchs the ticks user set, 
 *          during the timer interrupt user should reload the system tick using \ref SysTick_Reload function or similar function written by user, 
 *          so it can produce period timer interrupt. This function only available when __SYSTIMER_PRESENT == 1 and __CLIC_PRESENT == 1 
 */
__STATIC_FORCEINLINE wm_status_t SysTick_Config(uint64_t ticks)
{
    WM_ASSERT_RET(((uint32_t)ticks), RET_ERR_MTIMER_TICKS_INVALID);
    SysTimer_SetLoadCnt(0);
    SysTimer_SetCompareCnt((uint32_t)ticks);

    /* enable machine timer interrupt */  
    __clint_EnableInt(TIMER_INT);
    return RET_OK;
}
#endif /*if defined (__CLIC_PRESENT) && (__CLIC_PRESENT == 1)*/ 

/**
 * @brief  System Tick Reload
 * @details Reload the System Timer Tick when the MTIMECMP reached TIME value. Call this function in interrupt handler function to generate periodic interrupts.
 *          Since the MTIMERCMP value might overflow, if overflowed, MTIMER will be set to 0, and MTIMERCMP set to ticks
 * @param[in]  ticks  Number of ticks between two interrupts.
 * @return            0  Function succeeded.
             0x80070000  Function fail. ticks should not be zero.
 */
__STATIC_FORCEINLINE wm_status_t SysTick_Reload(uint64_t ticks)
{
    WM_ASSERT_RET(((uint32_t)ticks), RET_ERR_MTIMER_TICKS_INVALID);
    uint32_t cur_cnt    = (uint32_t)SysTimer_GetLoadCnt();
    uint32_t reload_cnt = cur_cnt + (uint32_t)ticks;

    if (reload_cnt > cur_cnt) {
        SysTimer_SetCompareCnt(reload_cnt);
    } else {
        SysTimer_SetLoadCnt(0);
        SysTimer_SetCompareCnt(ticks);
    }
    return RET_OK;
}
/** @}  End of Group WMSIS_SystemTick_Functions */
#endif /*defined(__TIMER_PRESENT) && (__TIMER_PRESENT == 1)*/
#endif /*__CORE_TIMER_H__*/

