/** @brief Provide hints to the compiler about the likelihood of a certain condition being true, which can help optimize branch prediction */
#define likely(x)                          __builtin_expect((x), 1)

/** @brief Provide hints to the compiler about the unlikelihood of a certain condition being true, which can help optimize branch prediction */
#define unlikely(x)                        __builtin_expect((x), 0)

/** @brief Round the value of a up to the nearest multiple of b. */
#define ROUNDUP(a, b)                      ((((a)-1) / (b)+1) * (b))

/** @brief Round the value of a down to the nearest multiple of b.*/
#define ROUNDDOWN(a, b)                    ((a )/ (b) * (b))

/** @brief Determine the maximum of two value a and b  */
#define MAX(a, b)                          ((a) > (b) ? (a) : (b))

/** @brief Determine the minimum of two value a and b  */
#define MIN(a, b)                          ((a) < (b) ? (a) : (b))

/** @brief Used to constrain a value a within a specified range defined by lo (the lower limit) and hi (the upper limit) */
#define CLAMP(a, lo, hi)                   MIN(MAX((a), (lo)), (hi))

/** @brief Extract a specific bit field from an integer value val, based on a bitmask which */
#define EXTRACT_FIELD(val, which)          (((val) & (which)) / ((which) & ~((which)-1)))

/** @brief Insert a bit field fieldval into an integer value val at a position specified by a bitmask which.  */
#define INSERT_FIELD(val, which, fieldval) (((val) & ~(which)) | ((fieldval) * ((which) & ~((which)-1))))

/** @brief Get a specific bit in val */
#define GET_BIT(val, x)                    ((val >> x) & 0x01)

/** @brief Set a specific bit in val */
#define SET_BIT(val, x)                    ((val) |= (1 << (x)))

/** @brief Clear a specific bit in val */
#define CLR_BIT(val, x)                    ((val) &= ~(1 << (x)))

/** @brief Check if a specific bit is set in val */
#define BIT_IS_SET(val, x)                 ((val) & (1 << (x)))

/** @brief Check if a specific bit is clear (not set) in val */
#define BIT_IS_CLR(val, x)                 (!BIT_IS_SET((val), (x)))

#define STR(x)                             XSTR(x)
#define XSTR(x)                            #x

/** @brief Checks whether a given integer x is a power of 2 or not. */
#define IS_POWER_OF_2(x)    (((x) > 0) && (!((x) & ((x) - 1))))

#ifdef __ASSEMBLY__
#define _AC(X,Y)                           (X)
#define _AT(T,X)                           (X)
#else
#define __AC(X,Y)                          (X##Y)
#define _AC(X,Y)                           __AC(X,Y)
#define _AT(T,X)                           ((T)(X))
#endif /* __ASSEMBLY__ */

#define _UL(x)                             (_AC(x, UL))
#define _ULL(x)                            (_AC(x, ULL))

#define _BITUL(x)                          (_UL(1) << (x))
#define _BITULL(x)                         (_ULL(1) << (x))

#define UL(x)                              (_UL(x))
#define ULL(x)                             (_ULL(x))

#define TRUE                               (1)
#define FALSE                              (0)


/** @brief Calculates the number of elements in a statically allocated array. */
#define ARRAY_SIZE(x)                      (sizeof(x) / sizeof(x[0]))

/** @brief  Breakpoint Instruction */
#define INST_BREAK                         __ASM_VOLATILE("ebreak")

/** @brief Check cond is true or not. If cond is not true, call breakpoint instruction */
#define WM_ASSERT(cond)                    {if (!(cond)) {INST_BREAK;}}

/** @brief Check cond is true or not. If cond is not true, return ret */
#define WM_ASSERT_RET(cond, ret)           {if (!(cond)) {return ret;}}

/** @brief Check return value ret is RET_OK or not, if ret is not RET_OK, return ret*/
#define WM_CHECK_RET(ret)                  {if ((RET_OK != ret)) {return ret;}}

/** @brief Wait until cond is TRUE */
#define WM_WAIT_FOREVER(cond)              while (!(cond)) { }
/** @} end of group WMSIS_COMMON_FUNCTIONS */

