// 轮常数（Key Expansion用）
static const uint8_t Rcon[11] = {
    0x00, 0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36};

uint8_t xtime(uint8_t x)
{
    return ((x << 1) ^ ((x >> 7) * 0x1B));
}

// GF(2^8)乘法（用于MixColumns）
uint8_t gf_mul(uint8_t a, uint8_t b)
{
    uint8_t res = 0;
    for (int i = 0; i < 8; i++)
    {
        if (b & 1)
            res ^= a;
        a = ((a << 1) ^ ((a >> 7) * 0x1B));
        // a = xtime(a);
        b >>= 1;
    }
    return res;
}
void KeyExpansion(const uint8_t *key, uint8_t *round_key)
{
    uint8_t temp[4];
    int i;

    // 初始轮密钥为输入密钥

    for (i = 0; i < 16; i++)
    {
        round_key[i] = key[i];
    }

    // 生成后续轮密钥
    for (i = 4; i < 44; i++)
    {
        temp[0] = round_key[(i - 1) * 4];
        temp[1] = round_key[(i - 1) * 4 + 1];
        temp[2] = round_key[(i - 1) * 4 + 2];
        temp[3] = round_key[(i - 1) * 4 + 3];

        if (i % 4 == 0)
        {
            // RotWord + SubWord + Rcon
            uint8_t tmp = temp[0];
            temp[0] = sbox[temp[1]] ^ Rcon[i / 4];
            temp[1] = sbox[temp[2]];
            temp[2] = sbox[temp[3]];
            temp[3] = sbox[tmp];
        }

        for (int j = 0; j < 4; j++)
        {
            round_key[i * 4 + j] = round_key[(i - 4) * 4 + j] ^ temp[j];
        }
    }
}

void SubBytes(uint8_t state[16])
{
    for (int i = 0; i < 16; i++)
    {
        state[i] = sbox[state[i]];
    }
}

void ShiftRows(uint8_t state[16])
{
    // uint8_t tmp[16];
    // for (int r = 0; r < 4; ++r)
    // { // 行
    //     for (int c = 0; c < 4; ++c)
    //     { // 列
    //         // 行r左移r字节
    //         tmp[4 * c + r] = state[4 * ((c + r) % 4) + r];
    //     }
    // }
    // // 拷贝回原始数组
    // for (int i = 0; i < 16; ++i)
    // {
    //     state[i] = tmp[i];
    // }
    uint8_t tmp;
    // Row 1: 左移1字节
    tmp = state[1];
    state[1] = state[5];
    state[5] = state[9];
    state[9] = state[13];
    state[13] = tmp;
    // Row 2: 左移2字节
    tmp = state[2];
    state[2] = state[10];
    state[10] = tmp;
    tmp = state[6];
    state[6] = state[14];
    state[14] = tmp;
    // Row 3: 左移3字节
    tmp = state[15];
    state[15] = state[11];
    state[11] = state[7];
    state[7] = state[3];
    state[3] = tmp;
}

void MixColumns(uint8_t state[16])
{
    for (int i = 0; i < 4; i++)
    {
        uint8_t a = state[i * 4];
        uint8_t b = state[i * 4 + 1];
        uint8_t c = state[i * 4 + 2];
        uint8_t d = state[i * 4 + 3];
        uint8_t s0_mul2 = ((a << 1) ^ ((a & 0x80) ? 0x1b : 0x00));
        uint8_t s1_mul2 = ((b << 1) ^ ((b & 0x80) ? 0x1b : 0x00));
        uint8_t s2_mul2 = ((c << 1) ^ ((c & 0x80) ? 0x1b : 0x00));
        uint8_t s3_mul2 = ((d << 1) ^ ((d & 0x80) ? 0x1b : 0x00));

        uint8_t s0_mul3 = s0_mul2 ^ a;
        uint8_t s1_mul3 = s1_mul2 ^ b;
        uint8_t s2_mul3 = s2_mul2 ^ c;
        uint8_t s3_mul3 = s3_mul2 ^ d;

        // 列混合，直接运算
        state[4 * i + 0] = s0_mul2 ^ s1_mul3 ^ c ^ d;
        state[4 * i + 1] = a ^ s1_mul2 ^ s2_mul3 ^ d;
        state[4 * i + 2] = a ^ b ^ s2_mul2 ^ s3_mul3;
        state[4 * i + 3] = s0_mul3 ^ b ^ c ^ s3_mul2;
    }
}

void AddRoundKey(uint8_t state[16], const uint8_t *round_key, int round)
{
    for (int i = 0; i < 16; i++)
    {
        state[i] ^= round_key[round * 16 + i];
    }
}
