void KeyExpansion_scalar(const uint8_t *key, uint8_t *round_key)
{
    uint8_t temp[4];

    // 初始轮密钥为输入密钥
    *(v4i32 *)&round_key[0] = *(v4i32 *)&key[0];
    // 生成后续轮密钥
    for (int i = 4; i < 44; i++)
    {
        *(uint32_t *)&temp[0] = *(uint32_t *)&round_key[(i - 1) * 4];
        if (i % 4 == 0)
        {
            // RotWord + SubWord + Rcon
            uint8_t tmp = temp[0];
            temp[0] = sbox[temp[1]] ^ Rcon[i / 4];
            temp[1] = sbox[temp[2]];
            temp[2] = sbox[temp[3]];
            temp[3] = sbox[tmp];
        }
        *(uint32_t *)&round_key[i * 4] = __builtin_riscv_eaddRoundKey(*(uint32_t *)&round_key[(i - 4) * 4], *(uint32_t *)&temp[0]);
        // __asm__ volatile("fence");
    }
}
