        *(uint32_t *)&state[4] = __builtin_riscv_eMixColumns(*(uint32_t *)&state[4]);
        *(uint32_t *)&state[8] = __builtin_riscv_eMixColumns(*(uint32_t *)&state[8]);
        *(uint32_t *)&state[12] = __builtin_riscv_eMixColumns(*(uint32_t *)&state[12]);
