        *(uint32_t *)&state[8] = __builtin_riscv_eaddRoundKey(*(uint32_t *)&state[8], *(uint32_t *)&round_key[round * 16 + 8]);
        *(uint32_t *)&state[12] = __builtin_riscv_eaddRoundKey(*(uint32_t *)&state[12], *(uint32_t *)&round_key[round * 16 + 12]);
