void AES_Encrypt_scalar(uint8_t *plaintext, const uint8_t *round_key)
{
    v16i8 vec_plaintext_main, vec_plaintext_main_tmp;

    // 初始轮密钥加
    AddRoundKey_scalar(plaintext, round_key, 0);

    // 9轮主循环
    for (int round = 1; round < 10; round++)
    {
        v16i8 vec_plaintext, vec_plaintext_tmp;
        SubBytes_scalar(&plaintext[0]);
        // ShiftRows_scalar(plaintext);
        vec_plaintext = __builtin_riscv_evld_v16i8((int32_t *)&plaintext[0], 0);
        vec_plaintext_tmp = __builtin_riscv_evshiftrows(vec_plaintext);
        // *(v4i32 *)&plaintext[0] = __builtin_riscv_evshiftrows(*(v4i32 *)&plaintext[0]);
        __builtin_riscv_evst(vec_plaintext_tmp, (int32_t *)&plaintext[0], 0);
        MixColumns_scalar(plaintext);
        AddRoundKey_scalar(&plaintext[0], round_key, round);
    }

    // 最终轮
    SubBytes_scalar(&plaintext[0]);
    // ShiftRows_scalar(&plaintext[0]);
    vec_plaintext_main = __builtin_riscv_evld_v16i8((int32_t *)&plaintext[0], 0);
    vec_plaintext_main_tmp = __builtin_riscv_evshiftrows(vec_plaintext_main);
    __builtin_riscv_evst(vec_plaintext_main_tmp, (int32_t *)&plaintext[0], 0);
    // *(v4i32 *)&plaintext[0] = __builtin_riscv_evshiftrows(*(v4i32 *)&plaintext[0]);
    AddRoundKey_scalar(&plaintext[0], round_key, 10);
}

