void KeyExpansion_vector(const uint8_t *key, uint8_t *round_key)
{
    uint8_t temp[4];

    // 初始轮密钥为输入密钥
    *(v16i8 *)&round_key[0] = *(v16i8 *)&key[0];

    // 生成后续轮密钥
    for (int i = 4; i < 44; i++)
    {
        *(uint32_t *)&temp[0] = *(uint32_t *)&round_key[(i - 1) * 4];

        if (i % 4 == 0)
        {
            // RotWord + SubWord + Rcon
            uint8_t tmp = temp[0];
            temp[0] = sbox[temp[1]] ^ Rcon[i / 4];
            temp[1] = sbox[temp[2]];
            temp[2] = sbox[temp[3]];
            temp[3] = sbox[tmp];
        }
        *(uint32_t *)&round_key[i * 4] = (*(uint32_t *)&round_key[(i - 4) * 4]) ^ (*(uint32_t *)&temp[0]);
    }
}

void AES_Encrypt_vector(uint8_t *plaintext, const uint8_t *round_key)
{
    v16i8 vec_plaintext_main, vec_round_key_main, vec_plaintext_main_tmp;
    v4i32 vec_plaintext_v4i32;
    vec_plaintext_main = __builtin_riscv_evld_v16i8(plaintext, 0);
    vec_round_key_main = __builtin_riscv_evld_v16i8(round_key, 0);
    vec_plaintext_main_tmp = __builtin_riscv_evaddRoundKey(vec_plaintext_main, vec_round_key_main);
    __builtin_riscv_evst(vec_plaintext_main_tmp, plaintext, 0);

    //*(v4i32 *)&plaintext[0] = __builtin_riscv_evaddRoundKey(*(v4i32 *)&plaintext[0], *(v4i32 *)&round_key[0]);

    // 9轮主循环
    v16i8 vec_plaintext, vec_round_key, vec_plaintext_tmp;
    v4i32 vec_plaintext_tmp_v4i32;
    for (int round = 1; round < 10; round++)
    {
        vec_plaintext = __builtin_riscv_evld_v16i8((int32_t *)&plaintext[0], 0);
        vec_plaintext_tmp_v4i32 = __builtin_riscv_evSubBytes(vec_plaintext);
        __builtin_riscv_evst(vec_plaintext_tmp_v4i32, (int32_t *)&plaintext[0], 0);

        vec_plaintext = __builtin_riscv_evld_v16i8((int32_t *)&plaintext[0], 0);
        vec_plaintext_tmp = __builtin_riscv_evshiftrows(vec_plaintext);
        __builtin_riscv_evst(vec_plaintext_tmp, (int32_t *)&plaintext[0], 0);

        vec_plaintext = __builtin_riscv_evld_v16i8((int32_t *)&plaintext[0], 0);
        vec_plaintext_tmp = __builtin_riscv_evMixColumns(vec_plaintext);
        __builtin_riscv_evst(vec_plaintext_tmp, (int32_t *)&plaintext[0], 0);

        vec_plaintext = __builtin_riscv_evld_v16i8((int32_t *)&plaintext[0], 0);
        vec_round_key = __builtin_riscv_evld_v16i8((int32_t *)&round_key[16 * round], 0);
        vec_plaintext_tmp = __builtin_riscv_evaddRoundKey(vec_plaintext, vec_round_key);
        __builtin_riscv_evst(vec_plaintext_tmp, (int32_t *)&plaintext[0], 0);

        // *(v4i32 *)&plaintext[0] = __builtin_riscv_evSubBytes(*(v4i32 *)&plaintext[0]);
        // *(v4i32 *)&plaintext[0] = __builtin_riscv_evshiftrows(*(v4i32 *)&plaintext[0]);
        // *(v4i32 *)&plaintext[0] = __builtin_riscv_evMixColumns(*(v4i32 *)&plaintext[0]);
        // *(v4i32 *)&plaintext[0] = __builtin_riscv_evaddRoundKey(*(v4i32 *)&plaintext[0], *(v4i32 *)&round_key[16 * round]);
    }

    // 最终轮
    // SubBytes_vector(&plaintext[0]);
    vec_plaintext_main = __builtin_riscv_evld_v16i8((int32_t *)&plaintext[0], 0);
    vec_plaintext_v4i32 = __builtin_riscv_evSubBytes(vec_plaintext_main);
    __builtin_riscv_evst(vec_plaintext_v4i32, (int32_t *)&plaintext[0], 0);

    vec_plaintext_main = __builtin_riscv_evld_v16i8((int32_t *)&plaintext[0], 0);
    vec_plaintext_main_tmp = __builtin_riscv_evshiftrows(vec_plaintext_main);
    __builtin_riscv_evst(vec_plaintext_main_tmp, (int32_t *)&plaintext[0], 0);

    vec_plaintext_main = __builtin_riscv_evld_v16i8((int32_t *)&plaintext[0], 0);
    vec_round_key_main = __builtin_riscv_evld_v16i8(round_key + 160, 0);
    vec_plaintext_main_tmp = __builtin_riscv_evaddRoundKey(vec_plaintext_main, vec_round_key_main);
    __builtin_riscv_evst(vec_plaintext_main_tmp, (int32_t *)&plaintext[0], 0);
    // *(v4i32 *)&plaintext[0] = __builtin_riscv_evSubBytes(*(v4i32 *)&plaintext[0]);
    // // *(v4i32 *)&plaintext[0] = __builtin_riscv_eaes128enfi(*(v4i32 *)&plaintext[0], *(v4i32 *)&round_key[160]);
    // *(v4i32 *)&plaintext[0] = __builtin_riscv_evshiftrows(*(v4i32 *)&plaintext[0]);
    // *(v4i32 *)&plaintext[0] = __builtin_riscv_evaddRoundKey(*(v4i32 *)&plaintext[0], *(v4i32 *)&round_key[160]);
}
