void AES_Encrypt(uint8_t *plaintext, const uint8_t *round_key)
{
    uint8_t state[16];
    memcpy(state, plaintext, 16);

    // 初始轮密钥加
    AddRoundKey(state, round_key, 0);

    // 9轮主循环
    for (int round = 1; round < 10; round++)
    {
        SubBytes(state);
        ShiftRows(state);
        MixColumns(state);
        AddRoundKey(state, round_key, round);
    }

    // 最终轮
    SubBytes(state);
    ShiftRows(state);
    AddRoundKey(state, round_key, 10);

    memcpy(plaintext, state, 16);
}

