void InvSubBytes_scalar(uint8_t *state)
{
    *(uint32_t *)&state[0] = __builtin_riscv_eInvSubBytes(*(uint32_t *)&state[0]);
    *(uint32_t *)&state[4] = __builtin_riscv_eInvSubBytes(*(uint32_t *)&state[4]);
    *(uint32_t *)&state[8] = __builtin_riscv_eInvSubBytes(*(uint32_t *)&state[8]);
    *(uint32_t *)&state[12] = __builtin_riscv_eInvSubBytes(*(uint32_t *)&state[12]);
}

void InvShiftRows_scalar(uint8_t *state)
{
    uint8_t tmp;
    // Row 1: 右移1字节
    tmp = state[13];
    state[13] = state[9];
    state[9] = state[5];
    state[5] = state[1];
    state[1] = tmp;
    // Row 2: 右移2字节
    tmp = state[2];
    state[2] = state[10];
    state[10] = tmp;
    tmp = state[6];
    state[6] = state[14];
    state[14] = tmp;
    // Row 3: 右移3字节
    tmp = state[3];
    state[3] = state[7];
    state[7] = state[11];
    state[11] = state[15];
    state[15] = tmp;
}

void InvMixColumns_scalar(uint8_t *state)
{
    // for (int c = 0; c < 4; c++)
    {
        *(uint32_t *)&state[0] = __builtin_riscv_eInvMixColumns(*(uint32_t *)&state[0]);
        *(uint32_t *)&state[4] = __builtin_riscv_eInvMixColumns(*(uint32_t *)&state[4]);
        *(uint32_t *)&state[8] = __builtin_riscv_eInvMixColumns(*(uint32_t *)&state[8]);
        *(uint32_t *)&state[12] = __builtin_riscv_eInvMixColumns(*(uint32_t *)&state[12]);
    }
}

void AES_Decrypt_scalar(uint8_t *ciphertext, const uint8_t *round_key)
{
    v16i8 vec_ciphertext_main, vec_ciphertext_main_tmp;
    // 初始轮密钥加（第10轮密钥）
    AddRoundKey_scalar(ciphertext, round_key, 10);

    // 9轮主循环（逆序）
    v16i8 vec_ciphertext, vec_ciphertext_tmp;
    for (int round = 9; round >= 1; round--)
    {
        vec_ciphertext = __builtin_riscv_evld_v16i8((int32_t *)&ciphertext[0], 0);
        vec_ciphertext_tmp = __builtin_riscv_evInvshiftrows(vec_ciphertext);
        __builtin_riscv_evst(vec_ciphertext_tmp, (int32_t *)&ciphertext[0], 0);
        InvSubBytes_scalar(&ciphertext[0]);
        AddRoundKey_scalar(&ciphertext[0], round_key, round);
        InvMixColumns_scalar(ciphertext);
    }

    // 最终轮
    vec_ciphertext_main = __builtin_riscv_evld_v16i8((int32_t *)&ciphertext[0], 0);
    vec_ciphertext_main_tmp = __builtin_riscv_evInvshiftrows(vec_ciphertext_main);
    __builtin_riscv_evst(vec_ciphertext_main_tmp, (int32_t *)&ciphertext[0], 0);
    InvSubBytes_scalar(&ciphertext[0]);
    AddRoundKey_scalar(&ciphertext[0], round_key, 0);

    // memcpy(ciphertext, state, 16);
}
