void InvSubBytes(uint8_t state[16])
{
    for (int i = 0; i < 16; i++)
    {
        state[i] = rsbox[state[i]];
    }
}

void InvShiftRows(uint8_t state[16])
{
    uint8_t tmp;
    // Row 1: 右移1字节
    tmp = state[13];
    state[13] = state[9];
    state[9] = state[5];
    state[5] = state[1];
    state[1] = tmp;
    // Row 2: 右移2字节
    tmp = state[2];
    state[2] = state[10];
    state[10] = tmp;
    tmp = state[6];
    state[6] = state[14];
    state[14] = tmp;
    // Row 3: 右移3字节
    tmp = state[3];
    state[3] = state[7];
    state[7] = state[11];
    state[11] = state[15];
    state[15] = tmp;
}

void InvMixColumns(uint8_t state[16])
{
    for (int c = 0; c < 4; c++)
    {
        uint8_t s0 = state[4 * c + 0];
        uint8_t s1 = state[4 * c + 1];
        uint8_t s2 = state[4 * c + 2];
        uint8_t s3 = state[4 * c + 3];

        // 乘以2
        uint8_t s0_2 = ((s0 << 1) ^ ((s0 & 0x80) ? 0x1b : 0x00));
        uint8_t s1_2 = ((s1 << 1) ^ ((s1 & 0x80) ? 0x1b : 0x00));
        uint8_t s2_2 = ((s2 << 1) ^ ((s2 & 0x80) ? 0x1b : 0x00));
        uint8_t s3_2 = ((s3 << 1) ^ ((s3 & 0x80) ? 0x1b : 0x00));

        // 乘以4
        uint8_t s0_4 = ((s0_2 << 1) ^ ((s0_2 & 0x80) ? 0x1b : 0x00));
        uint8_t s1_4 = ((s1_2 << 1) ^ ((s1_2 & 0x80) ? 0x1b : 0x00));
        uint8_t s2_4 = ((s2_2 << 1) ^ ((s2_2 & 0x80) ? 0x1b : 0x00));
        uint8_t s3_4 = ((s3_2 << 1) ^ ((s3_2 & 0x80) ? 0x1b : 0x00));

        // 乘以8
        uint8_t s0_8 = ((s0_4 << 1) ^ ((s0_4 & 0x80) ? 0x1b : 0x00));
        uint8_t s1_8 = ((s1_4 << 1) ^ ((s1_4 & 0x80) ? 0x1b : 0x00));
        uint8_t s2_8 = ((s2_4 << 1) ^ ((s2_4 & 0x80) ? 0x1b : 0x00));
        uint8_t s3_8 = ((s3_4 << 1) ^ ((s3_4 & 0x80) ? 0x1b : 0x00));

        // 乘以9: 8 + 1
        uint8_t s0_9 = s0_8 ^ s0;
        uint8_t s1_9 = s1_8 ^ s1;
        uint8_t s2_9 = s2_8 ^ s2;
        uint8_t s3_9 = s3_8 ^ s3;

        // 乘以11: 8 + 2 + 1
        uint8_t s0_11 = s0_8 ^ s0_2 ^ s0;
        uint8_t s1_11 = s1_8 ^ s1_2 ^ s1;
        uint8_t s2_11 = s2_8 ^ s2_2 ^ s2;
        uint8_t s3_11 = s3_8 ^ s3_2 ^ s3;

        // 乘以13: 8 + 4 + 1
        uint8_t s0_13 = s0_8 ^ s0_4 ^ s0;
        uint8_t s1_13 = s1_8 ^ s1_4 ^ s1;
        uint8_t s2_13 = s2_8 ^ s2_4 ^ s2;
        uint8_t s3_13 = s3_8 ^ s3_4 ^ s3;

        // 乘以14: 8 + 4 + 2
        uint8_t s0_14 = s0_8 ^ s0_4 ^ s0_2;
        uint8_t s1_14 = s1_8 ^ s1_4 ^ s1_2;
        uint8_t s2_14 = s2_8 ^ s2_4 ^ s2_2;
        uint8_t s3_14 = s3_8 ^ s3_4 ^ s3_2;

        state[4 * c + 0] = s0_14 ^ s1_11 ^ s2_13 ^ s3_9;
        state[4 * c + 1] = s0_9 ^ s1_14 ^ s2_11 ^ s3_13;
        state[4 * c + 2] = s0_13 ^ s1_9 ^ s2_14 ^ s3_11;
        state[4 * c + 3] = s0_11 ^ s1_13 ^ s2_9 ^ s3_14;
    }
}

void AES_Decrypt(uint8_t *ciphertext, const uint8_t *round_key)
{
    uint8_t state[16];
    memcpy(state, ciphertext, 16);

    // 初始轮密钥加（第10轮密钥）
    AddRoundKey(state, round_key, 10);

    // 9轮主循环（逆序）
    for (int round = 9; round >= 1; round--)
    {
        InvShiftRows(state);
        InvSubBytes(state);
        AddRoundKey(state, round_key, round);
        InvMixColumns(state);
    }

    // 最终轮
    InvShiftRows(state);
    InvSubBytes(state);
    AddRoundKey(state, round_key, 0);

    memcpy(ciphertext, state, 16);
}

